-- RC6.3 paper pass stall: the paper pass connection (holder of advisory lock PAPR 1346457682) sampled every 2 s
-- for 190 s: its current statement, state, wait event and statement age (SELECT only).
SELECT to_char(clock_timestamp(), 'HH24:MI:SS') AS t, a.pid, a.state, coalesce(a.wait_event_type, '-') AS wt, coalesce(a.wait_event, '-') AS we, round(extract(epoch FROM clock_timestamp() - a.query_start)::numeric, 1) AS q_age_s, left(regexp_replace(a.query, '\s+', ' ', 'g'), 150) AS q FROM pg_stat_activity a WHERE a.pid IN (SELECT pid FROM pg_locks WHERE locktype = 'advisory' AND objid = 1346457682 AND granted);
SELECT pg_sleep(2);
